<style>
:root{--ec10-gold:#dba621;--ec10-gold2:#f4c94c;--ec10-black:#050505;--ec10-ink:#171717;--ec10-soft:#f4f4f4;--ec10-red:#c80f18;--ec10-line:#ddd}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f4f4;color:var(--ec10-ink);font-family:"Be Vietnam Pro",sans-serif}.ec10-page a{color:inherit;text-decoration:none}.ec10-page img{display:block;max-width:100%}.ec10-page button,.ec10-page input{font:inherit}.ec10-container{width:min(1840px,calc(100% - 72px));margin-inline:auto}
.ec10-header{position:relative;z-index:30;background:#fff}.ec10-head-main{height:176px;display:grid;grid-template-columns:1fr 300px 1fr;align-items:center}.ec10-head-contact{display:flex;gap:34px}.ec10-head-contact a{display:flex;align-items:center;gap:12px;font-size:18px}.ec10-head-contact i{color:var(--ec10-gold);font-size:27px}.ec10-logo{display:flex;justify-content:center}.ec10-logo img{max-width:230px;max-height:120px;object-fit:contain}.ec10-logo span{display:grid;grid-template-columns:auto auto;align-items:end;font-family:"Playfair Display",serif;font-size:36px;line-height:.8}.ec10-logo i{grid-row:1/3;margin-right:5px;color:var(--ec10-gold);font-size:52px}.ec10-logo strong{grid-column:1/3;margin-top:7px;text-align:center;font-size:48px;letter-spacing:2px}.ec10-head-actions{display:flex;justify-content:flex-end;align-items:center;gap:19px}.ec10-head-actions form{display:flex;width:min(310px,48%);height:55px;border:3px solid #111;border-radius:30px;overflow:hidden}.ec10-head-actions input{min-width:0;flex:1;padding:0 16px;border:0;outline:0}.ec10-head-actions form button,.ec10-head-actions>button,.ec10-head-actions>a{position:relative;display:grid;place-items:center;width:45px;height:45px;border:0;background:transparent;font-size:28px;cursor:pointer}.ec10-head-actions em{position:absolute;right:-1px;top:-3px;display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--ec10-gold);font-size:11px;font-style:normal;color:#fff}.ec10-nav-wrap{background:#000;color:#fff}.ec10-nav-wrap .ec10-container{display:flex}.ec10-menu{display:none}.ec10-nav-wrap nav{display:flex;align-items:stretch}.ec10-nav-wrap nav a{padding:24px 26px;font-weight:700;white-space:nowrap}.ec10-nav-wrap nav a:hover,.ec10-nav-wrap nav a.is-active{background:var(--ec10-gold)}
.ec10-main{overflow:hidden}.ec10-hero{position:relative;width:min(1920px,100%);height:900px;margin:auto;background:#111;overflow:hidden}.ec10-hero-slide{position:absolute;inset:0;opacity:0;visibility:hidden;transition:.45s}.ec10-hero-slide.is-active{opacity:1;visibility:visible}.ec10-hero-slide>img{width:100%;height:100%;object-fit:cover}.ec10-hero-copy{position:absolute;right:8%;top:50%;width:min(560px,40%);transform:translateY(-50%);color:#fff;text-align:center;text-shadow:0 3px 15px #000}.ec10-hero-copy small{color:var(--ec10-gold2);font-weight:800;letter-spacing:3px}.ec10-hero-copy h1{margin:16px 0;font-family:"Playfair Display",serif;font-size:clamp(50px,5vw,90px);line-height:1}.ec10-hero-copy p{font-size:20px}.ec10-hero-copy a,.ec10-campaign a{display:inline-flex;margin-top:16px;padding:13px 26px;border:1px solid var(--ec10-gold);background:var(--ec10-gold);color:#111;font-weight:800}.ec10-arrow{position:absolute;z-index:2;top:50%;display:grid;place-items:center;width:48px;height:62px;border:0;background:#000a;color:#fff;cursor:pointer;transform:translateY(-50%)}.ec10-arrow.prev{left:0}.ec10-arrow.next{right:0}
.ec10-benefits{padding:44px 0;background:#ededed}.ec10-benefits .ec10-container{display:grid;grid-template-columns:repeat(4,1fr);gap:40px}.ec10-benefits article{display:flex;align-items:center;justify-content:center;gap:20px;min-height:190px;padding:24px;border:2px solid var(--ec10-gold);background:linear-gradient(135deg,#080808,#2b2b2b);color:#fff;text-align:center}.ec10-benefits i{color:var(--ec10-gold);font-size:52px}.ec10-benefits b{display:block;color:var(--ec10-gold);font-size:19px}.ec10-benefits p{margin:8px 0 0;line-height:1.5}
.ec10-section{padding:42px 0}.ec10-promo-shell{padding:22px;border-radius:7px;background:linear-gradient(120deg,#050505,#b68c17)}.ec10-promo-shell>header{display:flex;justify-content:space-between;align-items:center;color:#fff}.ec10-promo-shell h2{margin:0 0 22px;font-size:34px}.ec10-promo-shell h2 i{margin-right:10px;color:var(--ec10-gold2)}.ec10-promo-banners{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:28px}.ec10-promo-banners a{position:relative;overflow:hidden;height:285px;border-radius:6px}.ec10-promo-banners img{width:100%;height:100%;object-fit:cover}.ec10-promo-banners strong{position:absolute;left:25px;bottom:22px;padding:8px 12px;background:#000b;color:#fff;font-size:22px}.ec10-product-row{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:24px}.ec10-white-panel{padding:18px;border-radius:8px;background:#fff;box-shadow:0 2px 12px #0002}.ec10-tabs{display:flex;gap:14px;margin-bottom:38px}.ec10-tabs button,.ec10-ribbon-head button,.ec10-ribbon-head a{padding:13px 24px;border:1px solid #333;background:#fff;border-radius:4px;font-weight:700}.ec10-tabs button.is-active{background:#111;color:#fff}
.ec10-product{min-width:0;overflow:hidden;border-radius:6px;background:#fff;box-shadow:0 2px 11px #0002}.ec10-product-image{position:relative;display:block;aspect-ratio:1/.96;overflow:hidden}.ec10-product-image img{width:100%;height:100%;padding:12px;object-fit:contain;transition:.25s}.ec10-product:hover img{transform:scale(1.035)}.ec10-product-image>b{position:absolute;z-index:2;right:0;top:0;padding:10px 13px 25px;background:var(--ec10-red);color:#fff;text-align:center;clip-path:polygon(0 0,100% 0,100% 100%,50% 78%,0 100%)}.ec10-product-image>span{position:absolute;left:0;bottom:0;padding:7px 14px;border-radius:0 6px 0 0;background:#000;color:#fff}.ec10-product-image>span i{color:#ff3d26}.ec10-product-body{padding:15px}.ec10-product h3{min-height:52px;margin:0 0 13px;font-size:17px;line-height:1.45}.ec10-product-body p{display:flex;align-items:center;gap:14px;margin:0}.ec10-product strong{color:var(--ec10-red);font-size:19px}.ec10-product del{color:#888}.ec10-product small{display:block;margin-top:12px;padding:8px;border-left:3px solid var(--ec10-red);border-radius:5px;background:#eee;line-height:1.45}
.ec10-about{padding:60px 0;background:#000;color:#fff}.ec10-about .ec10-container{display:grid;grid-template-columns:1fr 1fr;align-items:stretch}.ec10-about .ec10-container>div{display:grid;place-content:center;padding:70px;text-align:center}.ec10-brand-mark{display:inline-grid;grid-template-columns:auto auto;width:max-content;margin:auto;font-family:"Playfair Display",serif;font-size:42px;line-height:.85}.ec10-brand-mark i{grid-row:1/3;margin-right:5px;color:var(--ec10-gold)}.ec10-brand-mark b{grid-column:1/3;font-size:58px}.ec10-about h2{color:var(--ec10-gold);font-size:32px}.ec10-about p{font-size:18px;line-height:1.65}.ec10-about img{width:100%;height:100%;min-height:510px;object-fit:cover}
.ec10-ribbon-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #333}.ec10-ribbon-head h2{min-width:390px;margin:0;padding:16px 28px;background:#000;color:#fff;clip-path:polygon(0 0,88% 0,100% 100%,0 100%);font-size:30px}.ec10-ribbon-head h2 i{margin-right:16px;color:var(--ec10-gold)}.ec10-ribbon-head>div{display:flex;gap:14px}.ec10-men-grid{display:grid;grid-template-columns:400px 1fr;gap:40px;padding-top:40px}.ec10-men-grid aside img{width:100%;height:610px;object-fit:cover}.ec10-men-grid aside h3{margin:22px 0 0;padding:12px;background:var(--ec10-gold);color:#fff;text-align:center}.ec10-men-grid aside p{display:flex;gap:7px;flex-wrap:wrap;margin:0;padding:10px;border:1px solid var(--ec10-gold)}.ec10-men-grid aside span{padding:6px 10px;border-radius:4px;background:#000;color:#fff}.ec10-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}
.ec10-campaign{padding:55px 0}.ec10-campaign .ec10-container{position:relative;height:460px;overflow:hidden;border-radius:7px;background:#000}.ec10-campaign img{width:100%;height:100%;object-fit:cover;filter:brightness(.68)}.ec10-campaign div>div{position:absolute;left:10%;top:50%;transform:translateY(-50%);color:#fff}.ec10-campaign small{color:var(--ec10-gold);font-weight:800}.ec10-campaign h2{max-width:600px;margin:12px 0;font-family:"Playfair Display",serif;font-size:52px;text-transform:uppercase}
.ec10-news-layout{display:grid;grid-template-columns:1.1fr 1fr 1.1fr;gap:30px;padding:45px 0 10px}.ec10-news-lead img{width:100%;height:350px;object-fit:cover}.ec10-news-layout h3{margin:12px 0 6px;line-height:1.45}.ec10-news-layout p{color:#626262;line-height:1.55}.ec10-news-list{display:grid;gap:18px}.ec10-news-list article{display:grid;grid-template-columns:150px 1fr;gap:15px}.ec10-news-list img{width:150px;height:105px;object-fit:cover}.ec10-news-list h3{margin:0;font-size:15px}.ec10-news-list p{margin:5px 0 0;font-size:13px}.ec10-news-art{width:100%;height:100%;min-height:520px;object-fit:cover}.ec10-brands{display:grid;grid-template-columns:repeat(6,1fr);gap:40px;padding:55px 0 20px}.ec10-brands a{display:grid;place-items:center;min-height:145px;border:1px solid #555;font-family:"Playfair Display",serif;font-size:27px;font-weight:800;text-align:center}
.ec10-footer{padding:70px 0;background:#000;color:#fff}.ec10-footer-brand{text-align:center}.ec10-footer-brand .ec10-brand-mark{font-size:35px}.ec10-footer-brand .ec10-brand-mark b{font-size:50px}.ec10-footer-brand>div{display:flex;justify-content:center;gap:14px;margin:24px 0 40px}.ec10-footer-brand>div a{display:grid;place-items:center;width:38px;height:38px;border-radius:8px;background:#fff;color:#111}.ec10-footer-grid{display:grid;grid-template-columns:1.35fr 1fr 1fr .85fr 1.35fr;gap:58px;border-top:1px solid #777;padding-top:50px}.ec10-footer h3{color:var(--ec10-gold);font-size:18px}.ec10-footer section>a,.ec10-footer section>p{display:block;margin:0 0 15px;line-height:1.55}.ec10-footer form{display:flex}.ec10-footer input{min-width:0;flex:1;height:46px;padding:0 12px;border:0}.ec10-footer button{border:0;background:var(--ec10-gold);font-weight:800}.ec10-pay,.ec10-market{color:var(--ec10-gold)}
.ec10-inner-hero{padding:52px 0;background:linear-gradient(135deg,#080808,#60470e);color:#fff}.ec10-inner-hero h1{font-size:42px}.ec10-content{padding:50px 0}.ec10-listing{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.ec10-form{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:25px;background:#fff}.ec10-form input,.ec10-form textarea,.ec10-form select{padding:13px;border:1px solid #ccc}.ec10-form textarea{grid-column:1/3}.ec10-button{display:inline-flex;padding:12px 22px;background:#000;color:#fff!important}
@media(max-width:1200px){.ec10-head-main{grid-template-columns:1fr 220px 1fr}.ec10-head-contact{display:grid;gap:10px}.ec10-nav-wrap nav a{padding-inline:15px;font-size:14px}.ec10-hero{height:680px}.ec10-product-row{grid-template-columns:repeat(4,1fr)}.ec10-product-row .ec10-product:last-child{display:none}.ec10-men-grid{grid-template-columns:300px 1fr}.ec10-product-grid{grid-template-columns:repeat(3,1fr)}.ec10-footer-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:900px){.ec10-container{width:min(100% - 28px,1840px)}.ec10-head-main{height:110px;grid-template-columns:1fr auto}.ec10-head-contact{display:none}.ec10-logo{justify-content:flex-start}.ec10-logo span{font-size:25px}.ec10-logo span strong{font-size:34px}.ec10-head-actions form{display:none}.ec10-menu{display:flex;align-items:center;gap:8px;padding:17px 0;border:0;background:transparent;color:#fff}.ec10-nav-wrap .ec10-container{display:block}.ec10-nav-wrap nav{display:none;position:absolute;left:0;right:0;background:#000}.ec10-nav-wrap nav.is-open{display:grid}.ec10-nav-wrap nav a{padding:14px 20px}.ec10-hero{height:560px}.ec10-hero-copy{right:10%;width:60%}.ec10-benefits .ec10-container{grid-template-columns:1fr 1fr}.ec10-product-row{grid-template-columns:repeat(3,1fr)}.ec10-product-row .ec10-product:nth-last-child(-n+2){display:none}.ec10-about .ec10-container{grid-template-columns:1fr}.ec10-men-grid{grid-template-columns:1fr}.ec10-men-grid aside{display:none}.ec10-product-grid{grid-template-columns:repeat(3,1fr)}.ec10-ribbon-head{align-items:flex-start;gap:15px;flex-direction:column}.ec10-ribbon-head>div{flex-wrap:wrap}.ec10-news-layout{grid-template-columns:1fr 1fr}.ec10-news-art{display:none}.ec10-brands{grid-template-columns:repeat(3,1fr)}}
@media(max-width:600px){.ec10-container{width:min(100% - 18px,1840px)}.ec10-head-actions{gap:5px}.ec10-head-actions>button,.ec10-head-actions>a{font-size:21px}.ec10-hero{height:500px}.ec10-hero-copy{left:50%;right:auto;top:auto;bottom:35px;width:88%;transform:translateX(-50%)}.ec10-hero-copy h1{font-size:38px}.ec10-benefits .ec10-container{grid-template-columns:1fr}.ec10-benefits article{min-height:130px}.ec10-promo-shell>header{display:block}.ec10-promo-banners{grid-template-columns:1fr}.ec10-promo-banners a{height:190px}.ec10-product-row{display:flex;overflow:auto;scroll-snap-type:x mandatory}.ec10-product-row .ec10-product{display:block!important;min-width:78%;scroll-snap-align:start}.ec10-tabs{overflow:auto}.ec10-tabs button{white-space:nowrap}.ec10-about .ec10-container>div{padding:45px 20px}.ec10-about img{min-height:330px}.ec10-product-grid{grid-template-columns:1fr 1fr;gap:10px}.ec10-ribbon-head h2{min-width:100%;font-size:24px}.ec10-ribbon-head button,.ec10-ribbon-head a{padding:9px 12px;font-size:12px}.ec10-campaign .ec10-container{height:330px}.ec10-campaign h2{font-size:34px}.ec10-news-layout{grid-template-columns:1fr}.ec10-news-list article{grid-template-columns:115px 1fr}.ec10-news-list img{width:115px}.ec10-brands{grid-template-columns:1fr 1fr;gap:10px}.ec10-brands a{min-height:95px;font-size:17px}.ec10-footer-grid{grid-template-columns:1fr;gap:28px}.ec10-listing{grid-template-columns:1fr}.ec10-form{grid-template-columns:1fr}.ec10-form textarea{grid-column:auto}}
</style>
